mapper.select:
SELECT b.*, m.*, COUNT(bl.board_like_id) as bln, COUNT(c.comment_id) as cn FROM board as b LEFT JOIN member as m ON b.member_id = m.member_id LEFT JOIN board_like as bl ON b.board_id = bl.board_id LEFT JOIN comment as c ON b.board_id = c.board_id WHERE board_status = 'ACTIVE'
AND b.board_type = #{boardType}
AND b.title LIKE CONCAT('%', #{keyword}, '%')
GROUP BY b.board_id ORDER BY b.created_at DESC
LIMIT #{pageSize}
OFFSET #{offset}

mapper.update:
UPDATE board
SET view_num = view_num+1
WHERE board_id = #{boardId}

mapper.select:
SELECT b.*
FROM board as b
WHERE b.board_id = #{boardId}

mapper.update:
UPDATE board
SET board_status = #{boardStatus}
WHERE board_id = #{boardId}

UPDATE board
SET board_type = #{boardType}, title = #{title}, content = #{content}
WHERE board_id = #{boardId}
